// All records below are synthetic. This prototype never connects to business APIs.
const corpSamples=[{id:'demo-a',name:'示例能源 A',stations:['滨江店','城北店','湖畔店']},{id:'demo-b',name:'示例能源 B',stations:['东城店','西城店','南湖店']}];
const privateState={corp:'demo-a',step:0,staff:[],range:'filter',relation:'all',tag:'',gender:'',bind:'',rooms:'',addedStart:'',addedEnd:'',members:'',exclude:false,excludeTag:'已参与活动',name:'周末会员权益通知',text:'本周末会员活动开启，欢迎查看活动页了解具体权益、适用门店与使用条件。',kind:'text',material:'会员权益海报',linkTitle:'会员专属活动',linkDesc:'查看权益、门店与适用条件',linkUrl:'',appTitle:'会员中心',appId:'',appPage:'',sendWay:'scheduled',sendTime:'2026-10-24T10:00',dryRun:true,preview:null,revision:0,ack:false,error:'',drafts:[],logs:[],statsType:'overview',start:'2026-10-01',end:'2026-10-22',statStaff:'',dimension:'staff',metric:'new',order:'desc',limit:10,threshold:'',statsResult:null,taskType:'customer',groupKeyword:'',groupOwner:'',groupClass:'',groupPage:1,groupSize:3,memberKeyword:'',qaInput:'',qaResult:null};
const qaChapters=[['后台登录、账号与权限','Q001–Q008','登录、坐席、扫码、管理组'],['对外信息与基础配置','Q009–Q011','头像、小程序、对外信息'],['客户添加、管理与流失','Q012–Q018','添加、客户中心、导出、流失'],['客户继承与离职交接','Q019–Q026','离职、交接、继承、转岗'],['标签体系与客户画像','Q027–Q040','标签、画像、CDP、人群包'],['渠道活码与 LBS','Q041–Q059','活码、二维码、LBS、扫码'],['欢迎语与素材','Q060–Q086','欢迎语、自动回复、素材'],['社群运营与标签建群','Q087–Q141','社群、群管理、建群、群公告'],['客户群发与朋友圈','Q142–Q177','群发、朋友圈、发送失败、SOP'],['客户裂变与拉新','Q178–Q189','裂变、助力、奖品、海报'],['会员绑定与商户平台','Q190–Q203','绑定、会员匹配、CRM、商户'],['任务中心与批量任务','Q204–Q212','任务中心、批量、更新数据'],['数据口径与报表差异','Q213–Q234','口径、对账、数据不一致、完成率、触达率'],['故障排查','Q235–Q240','故障、异常、同步失败、授权过期'],['数据安全与权限','Q241–Q245','权限、安全、脱敏、泄露']];
function demoCorp(){return corpSamples.find(c=>c.id===privateState.corp)}
function demoStaff(){return demoCorp().stations.map((station,i)=>({id:(privateState.corp==='demo-a'?100:200)+i+1,name:['员工甲','员工乙','员工丙'][i],station}))}
function demoCustomers(){const tags=['会员','新客户','活动关注'];return Array.from({length:18},(_,i)=>({id:privateState.corp+'-C'+(i+1),name:'示例客户 '+String(i+1).padStart(2,'0'),staff:demoStaff()[i%3].id,station:demoCorp().stations[i%3],tag:tags[i%3],tags:[tags[i%3],...(i%4===0?['已参与活动']:[])],gender:i%2?'女':'男',bound:i%3!==1,room:i%2===0,added:'2026-10-'+String(i+1).padStart(2,'0'),member:'M'+String(i+1).padStart(3,'0'),channel:['门店活码','活动页','员工推荐'][Math.floor(i/3)%3],lost:i===5||i===14}));}
function demoGroups(){return Array.from({length:6},(_,i)=>({id:privateState.corp+'-G'+i,name:demoCorp().stations[i%3]+['会员福利群','活动交流群'][Math.floor(i/3)],owner:demoStaff()[i%3],classify:['会员服务','活动运营'][Math.floor(i/3)],members:demoCustomers().filter((c,j)=>j%6===i),created:'2026-10-'+String(10+i).padStart(2,'0'),notice:'群内活动以正式说明为准，请勿发布无关内容。',incr:i%3,decr:i%2}));}
function demoTasks(type){return type==='customer'?[{id:'C-101',name:'会员权益提醒',target:12,sent:10,received:8,unsent:2,status:'已完成',date:'2026-10-20'},{id:'C-102',name:'新会员服务通知',target:6,sent:3,received:2,unsent:3,status:'发送中',date:'2026-10-22'}]:[{id:'G-201',name:'会员群活动公告',target:6,sent:5,received:4,unsent:1,status:'已完成',date:'2026-10-20'},{id:'G-202',name:'门店营业时间提醒',target:3,sent:0,received:0,unsent:3,status:'待发送',date:'2026-10-22'}]}
function privateLog(text){privateState.logs.push({at:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),corp:demoCorp().name,text})}
function renderPrivateLogs(){return privateState.logs.length?table(['时间','企业','操作'],privateState.logs.map(l=>[esc(l.at),esc(l.corp),esc(l.text)]).reverse()):'<div class="private-empty">当前会话暂无操作记录。示例查询或草案准备后将在这里显示。</div>'}
function privateContext(){return `<div class="private-context"><label for="privateCorp">当前企业 <select id="privateCorp" onchange="changePrivateCorp(this.value)">${corpSamples.map(c=>`<option value="${c.id}" ${privateState.corp===c.id?'selected':''}>${c.name} · 演示</option>`).join('')}</select></label><span>示例数据 · 未连接业务服务</span></div>`}
function changePrivateCorp(value){if(privateState.corp===value)return;privateState.corp=value;privateState.staff=[];Object.assign(privateState,{tag:'',gender:'',bind:'',rooms:'',members:'',addedStart:'',addedEnd:'',exclude:false});privateState.preview=null;privateState.step=0;privateState.ack=false;privateState.revision++;privateState.statsResult=null;privateState.statStaff='';privateState.groupOwner='';privateState.groupClass='';privateState.groupKeyword='';privateState.groupPage=1;privateState.qaResult=null;privateState.error='';render();toast('已切换企业，员工范围、预览和查询结果已重置')}
function privateWorkspace(){if(tabName==='执行记录')return `<div class="private-work">${privateContext()}<div class="video-card"><h3>当前会话记录</h3><p class="hint">只记录本次浏览器会话中的演示操作。</p>${renderPrivateLogs()}</div></div>`;return `<div class="private-work">${privateContext()}${current==='send'?sendWorkspace():current==='query'?statisticsWorkspace():current==='groups'?groupsWorkspace():qaWorkspace()}</div>`}
function privateError(){return privateState.error?`<div class="video-error" role="alert">${esc(privateState.error)}</div>`:''}
function invalidateSend(){privateState.revision++;privateState.preview=null;privateState.ack=false;privateState.error=''}
function setSendValue(key,value,draw=false){privateState[key]=value;invalidateSend();if(draw)render();else{renderPrivateRight();icons()}}
function pickStaff(id,checked){privateState.staff=checked?[...new Set([...privateState.staff,id])]:privateState.staff.filter(x=>x!==id);invalidateSend();render()}
function sendWorkspace(){let p=privateState;return `<div class="private-intro"><div class="avatar">${icon('send')}</div><div><h2>把消息，准确送到客户私聊</h2><p>客户 1 对 1 群发；群聊消息发送不在本模块内。</p></div></div><div class="private-stepper">${['选择员工','筛选客户','编辑消息','预览确认'].map((s,i)=>`<div class="${p.step===i?'selected':p.step>i?'done':''}"><span>${p.step>i?icon('check'):i+1}</span>${s}</div>`).join('')}</div>${privateError()}${[sendStaffStep,sendScopeStep,sendContentStep,sendPreviewStep][p.step]()}<p class="empty-note">仅准备本地演示草案，不会创建真实群发任务或向客户发送消息。</p>`}
function sendStaffStep(){let p=privateState;return `<div class="video-card"><h3>谁来执行客户群发？</h3><p class="hint">先确定企业与执行员工，再预览该员工名下的客户范围。</p><div class="field"><label for="sendName">任务名称</label><input id="sendName" value="${esc(p.name)}" maxlength="60" oninput="setSendValue('name',this.value)" placeholder="为这次客户触达取一个名字"></div><div class="panel-label"><span>选择执行员工 · 可多选</span><span>${p.staff.length} 人已选</span></div><div class="employee-picks">${demoStaff().map(s=>`<label class="employee-pick"><input type="checkbox" aria-label="选择${s.name}" ${p.staff.includes(s.id)?'checked':''} onchange="pickStaff(${s.id},this.checked)">${s.name}<small>${s.station} · 6 位示例客户</small></label>`).join('')}</div><div class="video-info">员工由企业下的员工列表选择，企业切换后需要重新选择，避免使用其他企业的客户范围。</div><div class="private-actions"><small>当前企业：${demoCorp().name}</small><button class="primary" onclick="sendNext()">下一步 · 筛选客户 ${icon('arrow-right')}</button></div></div>`}
function selectOptions(values,selected){return values.map(([value,label])=>`<option value="${esc(value)}" ${String(selected)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}
function pSelect(id,label,key,values){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" onchange="setSendValue('${key}',this.value)">${selectOptions(values,privateState[key])}</select></div>`}
function sendScopeStep(){let p=privateState;return `<div class="video-card"><h3>这条消息发给哪些客户？</h3><p class="hint">客户范围以已选员工为基础。下面的条件只在本地虚构数据中演示匹配。</p><div class="segmented" role="group" aria-label="客户范围">${[['all','全部客户'],['filter','按条件筛选'],['members','会员号名单']].map(([v,t])=>`<button class="${p.range===v?'selected':''}" aria-pressed="${p.range===v}" onclick="setSendValue('range','${v}',true)">${t}</button>`).join('')}</div>${p.range==='all'?'<div class="video-warning">将纳入所选员工名下全部示例客户，继续前请核对客户范围。</div>':p.range==='members'?`<div class="field"><label for="memberCodes">输入会员号名单</label><textarea id="memberCodes" oninput="setSendValue('members',this.value)" placeholder="每行一个，或用逗号分隔，例如 M001、M002">${esc(p.members)}</textarea></div><p class="hint">重复会员号自动去重；未匹配项会在预览中单独列出。</p>`:`<div class="form-grid">${pSelect('filterTag','客户标签','tag',[['','不限'],['会员','会员'],['新客户','新客户'],['活动关注','活动关注'],['已参与活动','已参与活动']])}${pSelect('filterGender','性别','gender',[['','不限'],['男','男'],['女','女']])}${pSelect('filterBind','会员绑定状态','bind',[['','不限'],['yes','已绑定'],['no','未绑定']])}${pSelect('filterRooms','所在群聊','rooms',[['','不限'],['yes','已入群'],['no','未入群']])}<div class="field"><label for="addedStart">添加时间 · 开始</label><input id="addedStart" type="date" value="${p.addedStart}" onchange="setSendValue('addedStart',this.value)"></div><div class="field"><label for="addedEnd">添加时间 · 结束</label><input id="addedEnd" type="date" value="${p.addedEnd}" onchange="setSendValue('addedEnd',this.value)"></div>${pSelect('filterRelation','多个筛选条件的关系','relation',[['all','同时满足（且）'],['any','满足任一（或）']])}</div>`}<div class="subtle-line"></div><label class="check-label"><input type="checkbox" ${p.exclude?'checked':''} onchange="setSendValue('exclude',this.checked,true)">排除带有指定标签的客户</label>${p.exclude?pSelect('excludeTag','排除客户标签','excludeTag',[['已参与活动','已参与活动'],['会员','会员'],['新客户','新客户']]):''}<div class="private-actions"><button class="secondary" onclick="sendBack()">上一步</button><button class="primary" onclick="sendNext()">下一步 · 编辑消息 ${icon('arrow-right')}</button></div></div>`}
function sendContentStep(){let p=privateState;return `<div class="video-card"><h3>准备客户收到的消息</h3><p class="hint">支持文本，以及附加图片、链接或小程序素材。素材使用演示库，不对外上传文件。</p><div class="field"><label for="sendText">消息正文</label><textarea id="sendText" maxlength="2000" oninput="setSendValue('text',this.value)" placeholder="写明客户权益、适用范围与活动条件">${esc(p.text)}</textarea></div><div class="field"><label for="messageKind">消息形式</label><select id="messageKind" onchange="setSendValue('kind',this.value,true)">${selectOptions([['text','仅文本'],['image','文本 + 图片'],['link','文本 + 链接'],['miniprogram','文本 + 小程序']],p.kind)}</select></div>${p.kind==='image'?pSelect('imageMaterial','从素材库选择图片','material',[['会员权益海报','会员权益海报'],['营业时间公告','营业时间公告']])+'<p class="hint">示例仅展示素材名称；正式接入后需要核实素材内容与有效期。</p>':p.kind==='link'?`<div class="form-grid"><div class="field"><label for="linkTitle">链接标题</label><input id="linkTitle" value="${esc(p.linkTitle)}" oninput="setSendValue('linkTitle',this.value)"></div><div class="field"><label for="linkDesc">链接描述</label><input id="linkDesc" value="${esc(p.linkDesc)}" oninput="setSendValue('linkDesc',this.value)"></div><div class="field full"><label for="linkUrl">链接地址</label><input id="linkUrl" type="url" value="${esc(p.linkUrl)}" oninput="setSendValue('linkUrl',this.value)" placeholder="https://example.com/activity"></div></div>`:p.kind==='miniprogram'?`<div class="form-grid"><div class="field"><label for="appTitle">小程序标题</label><input id="appTitle" value="${esc(p.appTitle)}" oninput="setSendValue('appTitle',this.value)"></div><div class="field"><label for="appId">小程序 AppID</label><input id="appId" value="${esc(p.appId)}" oninput="setSendValue('appId',this.value)" placeholder="素材库的小程序标识"></div><div class="field full"><label for="appPage">小程序页面路径</label><input id="appPage" value="${esc(p.appPage)}" oninput="setSendValue('appPage',this.value)" placeholder="pages/member/index"></div></div><p class="hint">正式接入后，从已配置素材库取得小程序及封面素材。</p>`:''}<div class="form-grid">${pSelect('sendWay','执行安排','sendWay',[['scheduled','定时发送'],['now','立即发送']])}${p.sendWay==='scheduled'?`<div class="field"><label for="sendTime">发送时间 · 北京时间</label><input id="sendTime" type="datetime-local" value="${esc(p.sendTime)}" onchange="setSendValue('sendTime',this.value)"></div>`:''}</div><label class="check-label"><input type="checkbox" ${p.dryRun?'checked':''} onchange="setSendValue('dryRun',this.checked)">正式接入后优先试运行，先核对范围与参数</label><div class="private-actions"><button class="secondary" onclick="sendBack()">上一步</button><button class="primary" onclick="previewSend()">${icon('scan-eye')} 预览客户范围与内容</button></div></div>`}
function sendValidation(stage=3){let p=privateState;if(!p.name.trim())return '请填写任务名称。';if(!p.staff.length)return '请至少选择一位执行员工。';if(stage>=1){if(p.addedStart&&p.addedEnd&&p.addedStart>p.addedEnd)return '添加时间开始日期不能晚于结束日期。';if(p.range==='members'&&!parseMemberCodes(p.members).length)return '请输入至少一个会员号。'}if(stage>=2){if(!p.text.trim())return '请填写消息正文。';if(p.kind==='link'){try{const u=new URL(p.linkUrl);if(!['http:','https:'].includes(u.protocol))throw Error()}catch{return '请填写有效的 HTTP 或 HTTPS 链接。'}if(!p.linkTitle.trim())return '请填写链接标题。'}if(p.kind==='miniprogram'&&(!p.appTitle.trim()||!p.appId.trim()||!p.appPage.trim()))return '请补全小程序标题、AppID 和页面路径。';if(p.sendWay==='scheduled'){if(!p.sendTime)return '请选择定时发送时间。';let t=p.sendTime.split('T')[1];if(!t||t<'09:00'||t>'21:00')return '示例发送时段为 09:00–21:00，请调整定时时间；实际限制以企业配置为准。';}}return ''}
function parseMemberCodes(value){return [...new Set(value.split(/[\s,，、;；]+/).map(x=>x.trim()).filter(Boolean))]}
function selectedCustomers(){let p=privateState,all=demoCustomers().filter(c=>p.staff.includes(c.staff));if(p.range==='members'){let codes=parseMemberCodes(p.members);all=all.filter(c=>codes.includes(c.member))}if(p.range==='filter')all=all.filter(c=>{let rules=[];if(p.tag)rules.push(c.tags.includes(p.tag));if(p.gender)rules.push(c.gender===p.gender);if(p.bind)rules.push(c.bound===(p.bind==='yes'));if(p.rooms)rules.push(c.room===(p.rooms==='yes'));if(p.addedStart)rules.push(c.added>=p.addedStart);if(p.addedEnd)rules.push(c.added<=p.addedEnd);return !rules.length||(p.relation==='all'?rules.every(Boolean):rules.some(Boolean))});if(p.exclude)all=all.filter(c=>!c.tags.includes(p.excludeTag));return all}
function scopeSummary(){let p=privateState,parts=[];if(p.range==='all')parts.push('所选员工全部客户');if(p.range==='members')parts.push('会员号名单 '+parseMemberCodes(p.members).length+' 个');if(p.range==='filter'){if(p.tag)parts.push('标签：'+p.tag);if(p.gender)parts.push('性别：'+p.gender);if(p.bind)parts.push(p.bind==='yes'?'已绑定会员':'未绑定会员');if(p.rooms)parts.push(p.rooms==='yes'?'已入群':'未入群');if(p.addedStart||p.addedEnd)parts.push('添加时间 '+(p.addedStart||'不限')+' 至 '+(p.addedEnd||'不限'));if(!parts.length)parts.push('未添加筛选条件，按全部客户匹配');parts.push('关系：'+(p.relation==='all'?'且':'或'))}if(p.exclude)parts.push('排除标签：'+p.excludeTag);return parts.join('；')}
function sendNext(){let err=sendValidation(privateState.step);if(err){privateState.error=err;render();return}privateState.error='';privateState.step=Math.min(privateState.step+1,2);render()}
function sendBack(){privateState.step=Math.max(0,privateState.step-1);privateState.ack=false;privateState.error='';render()}
function previewSend(){let p=privateState,err=sendValidation();if(err){p.error=err;render();return}let matches=selectedCustomers();p.preview={revision:p.revision,corp:p.corp,matches,unmatched:p.range==='members'?parseMemberCodes(p.members).filter(code=>!demoCustomers().some(c=>p.staff.includes(c.staff)&&c.member===code)):[]};p.step=3;p.ack=false;p.error='';privateLog('预览客户私聊群发范围：匹配 '+matches.length+' 位示例客户');render()}
function sendMessagePreview(p){return `<div class="message-preview"><div class="preview-label">客户私聊消息预览 · 仅为内容示意</div><div class="message-bubble">${esc(p.text)}</div>${p.kind==='text'?'':`<div class="attachment-preview">${icon(p.kind==='image'?'image':p.kind==='link'?'link':'smartphone')} ${esc(p.kind==='image'?p.material:p.kind==='link'?p.linkTitle:p.appTitle)}<p>${esc(p.kind==='image'?'图片素材 · 尚未加载实际图片':p.kind==='link'?p.linkDesc+' · '+p.linkUrl:p.appPage)}</p></div>`}</div>`}
function sendPreviewStep(){let p=privateState;if(!p.preview||p.preview.revision!==p.revision)return '<div class="video-card"><h3>需要重新预览</h3><p class="hint">范围或内容已发生变化，请重新确认。</p><button class="primary" onclick="privateState.step=2;render()">返回消息编辑</button></div>';let n=p.preview.matches.length;return `<div class="video-card"><h3>发送前，把范围和消息再核对一遍</h3><p class="hint">以下是本地示例数据匹配结果，不代表真实客户规模。</p>${metrics([['目标示例客户',n,'按客户唯一标识去重'],['执行员工',p.staff.length,'当前企业内已选员工'],['排除后范围',n,'仅匹配本页示例库']])}<div class="private-summary"><div class="kv"><span>企业 / 任务</span><b>${demoCorp().name} / ${esc(p.name)}</b></div><div class="kv"><span>员工</span><b>${demoStaff().filter(s=>p.staff.includes(s.id)).map(s=>s.name).join('、')}</b></div><div class="kv"><span>范围</span><b>${esc(scopeSummary())}</b></div><div class="kv"><span>执行时间</span><b>${p.sendWay==='now'?'立即发送（正式接入后）':esc(p.sendTime.replace('T',' '))+' · 北京时间'}</b></div><div class="kv"><span>试运行</span><b>${p.dryRun?'优先试运行':'正式执行前仍需业务确认'}</b></div></div>${sendMessagePreview(p)}${p.preview.unmatched.length?`<div class="video-warning">未在已选员工范围内匹配的会员号：${esc(p.preview.unmatched.join('、'))}</div>`:''}<h4 style="font-size:11px">员工范围明细</h4>${table(['员工','门店','匹配客户'],demoStaff().filter(s=>p.staff.includes(s.id)).map(s=>[s.name,s.station,p.preview.matches.filter(c=>c.staff===s.id).length+' 人']))}<div class="video-info">客户接收频次、素材有效期及企业可发送时段，需要正式服务返回确认。附件对接收频次有不同描述，本原型不将其显示为固定平台规则。</div><label class="check-label"><input id="sendAck" type="checkbox" ${p.ack?'checked':''} onchange="privateState.ack=this.checked;document.getElementById('saveSendDraft').disabled=!this.checked||privateState.preview.matches.length===0">我已核对客户范围、消息内容和执行时间，保存本地演示草案。</label><div class="private-actions"><button class="secondary" onclick="sendBack()">返回修改</button><button id="saveSendDraft" class="primary" onclick="saveSendDraft()" ${!p.ack||n===0?'disabled':''}>${icon('file-check-2')} 保存演示草案</button></div>${n===0?'<div class="video-warning">未匹配到客户，请返回调整筛选范围。</div>':''}</div>`}
function saveSendDraft(){let p=privateState;if(!p.preview||p.preview.revision!==p.revision||p.preview.corp!==p.corp||!p.ack||!p.preview.matches.length){toast('请重新预览并确认客户范围');return}let key=p.corp+':'+p.revision;let existing=p.drafts.find(d=>d.key===key);if(existing){viewSendDraft(existing.id);return}let draft={id:'D'+Date.now()+'-'+p.drafts.length,key,corp:p.corp,corpName:demoCorp().name,name:p.name,count:p.preview.matches.length,scope:scopeSummary(),staff:demoStaff().filter(s=>p.staff.includes(s.id)).map(s=>s.name).join('、'),text:p.text,kind:p.kind,material:p.material,linkTitle:p.linkTitle,linkDesc:p.linkDesc,linkUrl:p.linkUrl,appTitle:p.appTitle,appPage:p.appPage,sendTime:p.sendWay==='now'?'正式接入后立即执行':p.sendTime.replace('T',' ')+' · 北京时间',dryRun:p.dryRun,cancelled:false};p.drafts.push(draft);privateLog('保存本地草案：'+draft.name+'；未提交、未发送');viewSendDraft(draft.id);renderPrivateRight();icons()}
function viewSendDraft(id){let d=privateState.drafts.find(d=>d.id===id);if(!d)return;modal(`<h2 id="modal-title">${esc(d.name)}</h2><p>${esc(d.corpName)} · ${d.cancelled?'已取消草案':'本地演示草案'} · 未创建真实群发</p><div class="summary-card"><div class="kv"><span>客户范围</span><b>${d.count} 位示例客户</b></div><div class="kv"><span>执行员工</span><b>${esc(d.staff)}</b></div><div class="kv"><span>筛选条件</span><b>${esc(d.scope)}</b></div><div class="kv"><span>安排</span><b>${esc(d.sendTime)}</b></div></div>${sendMessagePreview(d)}<div class="notice">当前仅保存页面内草案。未进行真实试运行，也未向业务服务提交发送请求。</div><div class="modal-footer">${!d.cancelled?`<button class="secondary" onclick="cancelSendDraft('${d.id}')">取消本地草案</button>`:''}<button class="primary" onclick="closeModal();navigate('files')">查看成果库</button></div>`)}
function cancelSendDraft(id){let d=privateState.drafts.find(d=>d.id===id);if(!d||d.cancelled)return;modal(`<h2 id="modal-title">取消本地草案？</h2><p>草案：${esc(d.name)}<br>状态：待业务接入，未发送。</p><p>此操作只取消本页草案，不会取消外部系统中的群发任务。</p><div class="modal-footer"><button class="secondary" onclick="viewSendDraft('${d.id}')">保留草案</button><button class="primary" onclick="confirmCancelSendDraft('${d.id}')">确认取消草案</button></div>`)}
function confirmCancelSendDraft(id){let d=privateState.drafts.find(d=>d.id===id);if(!d)return;d.cancelled=true;privateLog('取消本地草案：'+d.name);viewSendDraft(id)}
function statsValue(k,v,draw=false){privateState[k]=v;privateState.statsResult=null;if(draw)render();else{let target=$('#statsOutput');if(target)target.innerHTML='<div class="private-empty">筛选已修改，点击查询更新示例结果。</div>';renderPrivateRight();icons()}}
function statisticsWorkspace(){let p=privateState;return `<div class="private-intro"><div class="avatar">${icon('chart-no-axes-combined')}</div><div><h2>看清增长，也看清触达</h2><p>按企业、日期和员工查询；所有结果均为只读示例。</p></div></div><div class="private-pill-tabs">${[['overview','客户总览'],['rank','拉新排行'],['retention','留存趋势'],['groups','群聊统计'],['tasks','群发效果']].map(([v,t])=>`<button class="${p.statsType===v?'selected':''}" onclick="statsValue('statsType','${v}',true)">${t}</button>`).join('')}</div><div class="video-card"><div class="stats-toolbar"><div class="field"><label for="statsStart">开始日期</label><input id="statsStart" type="date" value="${p.start}" onchange="statsValue('start',this.value)"></div><div class="field"><label for="statsEnd">结束日期</label><input id="statsEnd" type="date" value="${p.end}" onchange="statsValue('end',this.value)"></div>${p.statsType==='overview'?`<div class="field"><label for="statsStaff">员工范围</label><select id="statsStaff" onchange="statsValue('statStaff',this.value)">${selectOptions([['','全部员工'],...demoStaff().map(s=>[s.id,s.name])],p.statStaff)}</select></div>`:''}<button class="primary" onclick="runPrivateStats()">${icon('search')} 查询</button></div>${p.statsType==='rank'?`<div class="stats-controls"><div class="field"><label for="rankDimension">排行维度</label><select id="rankDimension" onchange="statsValue('dimension',this.value)">${selectOptions([['staff','员工'],['station','油站'],['channel','渠道']],p.dimension)}</select></div><div class="field"><label for="rankMetric">排行指标</label><select id="rankMetric" onchange="statsValue('metric',this.value)">${selectOptions([['new','新增客户'],['lost','流失客户'],['bound','绑定客户'],['rate','绑定率'],['total','客户总数']],p.metric)}</select></div><div class="field"><label for="rankOrder">排序</label><select id="rankOrder" onchange="statsValue('order',this.value)">${selectOptions([['desc','从高到低'],['asc','从低到高']],p.order)}</select></div><div class="field"><label for="rankLimit">展示条数 · 1–100</label><input id="rankLimit" type="number" min="1" max="100" value="${p.limit}" onchange="statsValue('limit',Number(this.value))"></div><div class="field"><label for="rankThreshold">低于阈值 · 可选</label><input id="rankThreshold" type="number" value="${p.threshold}" onchange="statsValue('threshold',this.value)" placeholder="如绑定率低于 50%"></div></div>`:p.statsType==='tasks'?`<div class="segmented" role="group" aria-label="群发统计类型">${[['customer','客户私聊群发'],['group','客户群聊群发']].map(([v,t])=>`<button class="${p.taskType===v?'selected':''}" onclick="statsValue('taskType','${v}',true)">${t}</button>`).join('')}</div><p class="hint">“客户群聊群发”只展示历史统计，当前未提供群消息发送入口。</p>`:''}<div id="statsOutput">${p.statsResult?statsResultHtml():`<div class="private-empty">${icon('chart-no-axes-combined')}选择统计范围后，点击查询查看结果。</div>`}</div></div>`}
function statsBase(){let p=privateState;return demoCustomers().filter(c=>(!p.start||c.added>=p.start)&&(!p.end||c.added<=p.end))}
function runPrivateStats(){let p=privateState;if(!p.start||!p.end||p.start>p.end){toast('请填写有效的起止日期');return}if(p.statsType==='rank'&&(!Number.isInteger(p.limit)||p.limit<1||p.limit>100)){toast('排行条数需要为 1–100 的整数');return}p.statsResult={corp:p.corp,start:p.start,end:p.end,type:p.statsType};privateLog('查询'+({overview:'客户总览',rank:'运营排行',retention:'留存趋势',groups:'群聊统计',tasks:'群发效果'})[p.statsType]+'（示例）');render()}
function percent(n,d){return d?(n/d*100).toFixed(1)+'%':'—'}
function statsResultHtml(){let p=privateState,data=statsBase(),stamp=`<div class="qa-source">数据源：本地虚构示例 · 企业：${demoCorp().name}<br>查询区间：${p.start} 至 ${p.end}（含首尾日期） · 非真实业务查询</div>`;if(p.statsType==='overview'){let rows=demoCustomers().filter(c=>!p.statStaff||c.staff===Number(p.statStaff)),growth=data.filter(c=>!p.statStaff||c.staff===Number(p.statStaff));return `<div class="metric-grid four">${[['客户总数',rows.length,'示例客户库当前快照'],['区间新增',growth.length,'按示例添加日期'],['绑定客户',rows.filter(c=>c.bound).length,'当前快照中的绑定数'],['标记流失',growth.filter(c=>c.lost).length,'示例以添加日期筛选']].map(x=>`<div class="metric"><small>${x[0]}</small><strong>${x[1]}</strong><em>${x[2]}</em></div>`).join('')}</div><p class="private-result-note">当前快照绑定率：${percent(rows.filter(c=>c.bound).length,rows.length)}（绑定客户 / 客户总数）。示例没有真实流失事件时间，不能用它判断区间真实流失。</p>${stamp}`}
if(p.statsType==='rank'){let names=p.dimension==='staff'?demoStaff().map(s=>s.name):p.dimension==='station'?demoCorp().stations:['门店活码','活动页','员工推荐'];let list=names.map(name=>{let subset=data.filter(c=>p.dimension==='staff'?demoStaff().find(s=>s.id===c.staff).name===name:p.dimension==='station'?c.station===name:c.channel===name);return {name,value:p.metric==='rate'?(subset.length?subset.filter(c=>c.bound).length/subset.length*100:null):subset.filter(c=>p.metric==='lost'?c.lost:p.metric==='bound'?c.bound:true).length}}).filter(r=>p.threshold===''||r.value!==null&&r.value<Number(p.threshold)).sort((a,b)=>(p.order==='asc'?1:-1)*((a.value??-1)-(b.value??-1))).slice(0,p.limit);return `<h3 style="margin-top:15px">${{staff:'员工',station:'油站',channel:'渠道'}[p.dimension]}排行 · 示例</h3>${table(['排名','对象',p.metric==='rate'?'绑定率':'客户数'],list.map((r,i)=>[i+1,r.name,r.value===null?'—':p.metric==='rate'?r.value.toFixed(1)+'%':r.value]))}<p class="private-result-note">按查询日期内添加的示例客户计算。绑定率分母为对应对象的示例客户数，分母为 0 时显示“—”。</p>${stamp}`}
if(p.statsType==='retention'){return `<h3 style="margin-top:16px">留存趋势 · 演示结构</h3><div class="video-warning">附件未提供留存率的具体人群与分母定义，当前不计算留存率，也不将增长率替代为留存率。</div>${table(['日期','留存率','状态'],[p.start,p.end].filter((x,i,a)=>a.indexOf(x)===i).map(d=>[d,'—','等待业务服务返回']))}${stamp}`}
if(p.statsType==='groups'){let groups=demoGroups().filter(g=>g.created>=p.start&&g.created<=p.end);return `${metrics([['区间建群数',groups.length,'按创建日期筛选'],['群成员记录数',groups.reduce((s,g)=>s+g.members.length,0),'按群累加，非跨群去重'],['群分组',new Set(groups.map(g=>g.classify)).size,'当前匹配分组']])}${table(['群分组','群数','成员记录数'],['会员服务','活动运营'].map(name=>[name,groups.filter(g=>g.classify===name).length,groups.filter(g=>g.classify===name).reduce((s,g)=>s+g.members.length,0)]))}<p class="private-result-note">群统计使用创建日期，当前客户示例与群样本的统计范围不同。</p>${stamp}`}
let tasks=demoTasks(p.taskType).filter(t=>t.date>=p.start&&t.date<=p.end);return `<h3 style="margin-top:15px">${p.taskType==='customer'?'客户私聊':'客户群聊'}群发记录</h3>${table(['任务','目标'+(p.taskType==='customer'?'客户':'群'),'已触达','触达率','状态','详情'],tasks.map(t=>[t.name,t.target,t.received,percent(t.received,t.target),'<span class="state-chip '+(t.status==='已完成'?'':'amber')+'">'+t.status+'</span>',`<button class="link" onclick="sendTaskDetail('${p.taskType}','${t.id}','summary')">查看 →</button>`]))}<p class="private-result-note">触达率 = 已触达 / 目标数量。任务“已完成”不代表全部送达；“未发送”可能包含在“未触达”内，不能直接相加。</p>${stamp}`}
function sendTaskDetail(type,id,tab){let t=demoTasks(type).find(t=>t.id===id);if(!t)return;let unit=type==='customer'?'客户':'群';let body=tab==='summary'?`${metrics([['目标'+unit,t.target,'任务记录'],['已触达',t.received,'以送达回执为准'],['触达率',percent(t.received,t.target),'已触达 / 目标']])}<div class="kv"><span>已发送</span><b>${t.sent}</b></div><div class="kv"><span>未发送</span><b>${t.unsent}</b></div><div class="kv"><span>未触达</span><b>${t.target-t.received}</b></div><p class="private-result-note">已发送与已送达分别展示；统计只反映示例回执。</p>`:tab==='receive'?table([unit,'执行员工','接收状态'],Array.from({length:t.target},(_,i)=>[(type==='customer'?'示例客户 ':'示例群 ')+(i+1),demoStaff()[i%3].name,i<t.received?'已送达':i<t.sent?'已发送，待送达':'未发送'])):table([type==='customer'?'员工':'群主','目标'+unit,'已发送','未发送'],demoStaff().map((s,j)=>{let target=Array.from({length:t.target},(_,i)=>i).filter(i=>i%3===j),sent=target.filter(i=>i<t.sent).length;return[s.name,target.length,sent,target.length-sent]}));modal(`<h2 id="modal-title">${t.name}</h2><p>${demoCorp().name} · ${t.date} · ${t.status} · 示例历史任务</p><div class="private-pill-tabs">${[['summary','统计概览'],['receive',unit+'接收明细'],['staff',type==='customer'?'员工发送明细':'群主发送明细']].map(([v,n])=>`<button class="${tab===v?'selected':''}" onclick="sendTaskDetail('${type}','${id}','${v}')">${n}</button>`).join('')}</div>${body}<div class="qa-source">预设示例任务，不是本页草案的实际发送结果。</div>`)}
function groupMatches(){let p=privateState;return demoGroups().filter(g=>(!p.groupKeyword||g.name.includes(p.groupKeyword))&&(!p.groupOwner||String(g.owner.id)===p.groupOwner)&&(!p.groupClass||g.classify===p.groupClass))}
function setGroupFilter(k,value){privateState[k]=value;privateState.groupPage=1;render()}
function groupsWorkspace(){let p=privateState,all=groupMatches(),pages=Math.max(1,Math.ceil(all.length/p.groupSize));p.groupPage=Math.min(p.groupPage,pages);let rows=all.slice((p.groupPage-1)*p.groupSize,p.groupPage*p.groupSize);return `<div class="private-intro"><div class="avatar">${icon('messages-square')}</div><div><h2>找到群，了解群里的情况</h2><p>群聊列表、群主、分组和成员的只读查询。</p></div></div><div class="video-card"><div class="group-toolbar"><div class="field"><label for="groupKeyword">群名关键词</label><input id="groupKeyword" value="${esc(p.groupKeyword)}" placeholder="例如：滨江、会员" onkeydown="if(event.key==='Enter')searchGroups()"></div><div class="field"><label for="groupOwner">群主</label><select id="groupOwner" onchange="setGroupFilter('groupOwner',this.value)">${selectOptions([['','全部群主'],...demoStaff().map(s=>[s.id,s.name])],p.groupOwner)}</select></div><div class="field"><label for="groupClass">群分组</label><select id="groupClass" onchange="setGroupFilter('groupClass',this.value)">${selectOptions([['','全部分组'],['会员服务','会员服务'],['活动运营','活动运营']],p.groupClass)}</select></div></div><button class="primary" onclick="searchGroups()">${icon('search')} 搜索群聊</button><div class="panel-label"><span>示例群聊 · ${all.length} 个</span><span>第 ${p.groupPage} / ${pages} 页</span></div>${table(['群名称','群主','成员','分组','操作'],rows.map(g=>[esc(g.name),g.owner.name,g.members.length+' 人',g.classify,`<button class="link" onclick="groupDetail('${g.id}','info')">查看详情 →</button>`]))}<div class="private-actions"><small>每页 ${p.groupSize} 条</small><div><button class="secondary" ${p.groupPage===1?'disabled':''} onclick="privateState.groupPage--;render()">上一页</button> <button class="secondary" ${p.groupPage>=pages?'disabled':''} onclick="privateState.groupPage++;render()">下一页</button></div></div><div class="qa-source">本地虚构群聊 · 成员数量按示例成员列表计算 · 不读取聊天内容。</div></div>`}
function searchGroups(){privateState.groupKeyword=$('#groupKeyword').value.trim();privateState.groupPage=1;privateLog('查询群聊：'+(privateState.groupKeyword||'全部示例群'));render()}
function groupDetail(id,tab){let g=demoGroups().find(g=>g.id===id);if(!g)return;let members=g.members.filter(m=>!privateState.memberKeyword||m.name.includes(privateState.memberKeyword));modal(`<h2 id="modal-title">${esc(g.name)}</h2><p>${demoCorp().name} · 只读示例</p><div class="private-pill-tabs"><button class="${tab==='info'?'selected':''}" onclick="groupDetail('${id}','info')">群详情</button><button class="${tab==='members'?'selected':''}" onclick="groupDetail('${id}','members')">群成员 · ${g.members.length}</button></div>${tab==='info'?`<div class="summary-card"><div class="kv"><span>群主</span><b>${g.owner.name}</b></div><div class="kv"><span>所属分组</span><b>${g.classify}</b></div><div class="kv"><span>创建日期</span><b>${g.created}</b></div><div class="kv"><span>成员总数</span><b>${g.members.length}</b></div><div class="kv"><span>今日入群 / 退群</span><b>${g.incr} / ${g.decr}（独立示例事件）</b></div></div><h4 style="font-size:11px">群公告</h4><p>${esc(g.notice)}</p>`:`<div class="field"><label for="memberSearch">成员名称搜索</label><input id="memberSearch" value="${esc(privateState.memberKeyword)}" placeholder="输入名称后回车" onkeydown="if(event.key==='Enter'){privateState.memberKeyword=this.value.trim();groupDetail('${id}','members')}"></div>${table(['成员名称','类型','入群方式','加入日期'],members.map(m=>[m.name,'外部联系人','示例邀请',m.added]))}`}<div class="qa-source">当前未接入群信息同步，展示的是示例数据；不会修改成员或群公告。</div>`)}
const qaFacts=[{test:q=>/1对1|1 对 1|区别|私聊/.test(q),title:'客户群发与群聊群发有什么区别？',answer:'客户群发将消息发送到客户的 1 对 1 私聊，按执行员工与客户条件筛选；群聊群发将消息发送到群内，通常按群主、群分组或指定群确定范围。本页提供客户私聊草案，群聊发送仅支持历史效果查询。',source:'客户群发 Skill · 与群群发的区别'}, {test:q=>/触达率|完成率|送达|已发送|完成.*收到/.test(q),title:'怎样理解触达率与发送状态？',answer:'客户私聊群发的触达率为“已触达客户数 / 目标客户数”；群聊群发为“已触达群数 / 目标群数”。已发送和已送达是不同状态，任务完成也不能直接理解为所有目标都收到。可以查看任务的接收明细与员工发送明细。',source:'统计查询 Skill · 群发统计与触达率'}, {test:q=>/筛选|会员号|名单|标签.*客户/.test(q),title:'客户群发支持哪些客户筛选？',answer:'所提供的客户群发流程支持按执行员工、客户标签、性别、添加时间、所在群聊和会员绑定状态筛选，也支持按会员号名单匹配及排除客户。正式创建前需要先预览范围，并确认客户数量、筛选条件和消息内容。',source:'客户群发 Skill · 预览发送范围与操作确认'}, {test:q=>/排行|拉新|统计.*维度/.test(q),title:'可以按哪些维度查看运营排行？',answer:'统计查询支持员工、油站和渠道三个排行维度。可查看新增客户、流失客户、绑定客户、绑定率和客户总数，选择升序或降序，并筛选日期和阈值。排行返回条数最多 100。',source:'统计查询 Skill · 拉新排行'}, {test:q=>/群成员|群主|群详情/.test(q),title:'群聊查询可以查看什么？',answer:'群聊查询支持企业内的群聊搜索、群列表、群详情、群成员、员工与群分组。群详情包含群主、成员数、入退群统计、公告和创建时间；这些能力为只读查询，不会编辑群公告或调整成员。',source:'群聊查询 Skill · 群详情与群成员'}];
function qaWorkspace(){let p=privateState;return `<div class="private-intro"><div class="avatar">${icon('book-open-text')}</div><div><h2>运营问题，先找可靠依据</h2><p>查看知识目录，区分已有依据和需要补充的知识。</p></div></div><div class="video-card"><h3>你遇到了什么问题？</h3><div class="field qa-question"><textarea id="qaQuestion" placeholder="例如：客户群发和群聊群发有什么区别？">${esc(p.qaInput)}</textarea></div><div class="private-actions"><small>知识目录已载入 · 问答正文待补充</small><button class="primary" onclick="askPrivateQa()">${icon('search')} 查找依据</button></div><div class="qa-highlights">${['客户群发与群聊群发的区别','如何计算触达率？','可以按哪些维度排行？','群发失败怎么排查？'].map(q=>`<button onclick="askPrivateQa('${q}')">${q}</button>`).join('')}</div>${p.qaResult?qaResultHtml():''}</div><div class="panel-label"><span>运营知识目录 · 15 个章节</span><span>目录标注 245 问</span></div><div class="qa-category-grid">${qaChapters.map((c,i)=>`<button class="qa-category" onclick="openQaChapter(${i})"><strong>${String(i+1).padStart(2,'0')} / ${c[0]}</strong><small>${c[1]} · 正文待接入</small></button>`).join('')}</div><p class="private-result-note">当前附件仅包含 15 章目录和检索规则，未附问题正文。页面不会将目录介绍当成完整问答库。</p>`}
function askPrivateQa(q){let p=privateState;p.qaInput=typeof q==='string'?q:$('#qaQuestion').value.trim();if(!p.qaInput){toast('请输入运营问题');return}let fact=qaFacts.find(f=>f.test(p.qaInput));let chapterIds=qaChapters.map((c,i)=>({i,score:c[2].split('、').filter(k=>p.qaInput.includes(k)).length})).filter(x=>x.score).sort((a,b)=>b.score-a.score).slice(0,3).map(x=>x.i);p.qaResult={fact:fact?qaFacts.indexOf(fact):-1,chapters:chapterIds};privateLog('查找运营问题依据：'+p.qaInput);render()}
function qaResultHtml(){let r=privateState.qaResult;return `<div class="subtle-line"></div>${r.fact>=0?`<span class="qa-match">已匹配所提供的业务 Skill</span><h3>${qaFacts[r.fact].title}</h3><div class="qa-answer">${qaFacts[r.fact].answer}</div><div class="qa-source">依据：${qaFacts[r.fact].source}<br>这是对已提供文档的摘要；不代表业务服务的实时状态。</div>`:`<span class="qa-match">需要知识库正文</span><div class="qa-answer">${r.chapters.length?'已找到相关章节，但缺少具体问答正文，当前无法给出有依据的标准答案。':'当前目录未找到明确匹配项，完整问答正文尚未接入，暂不生成标准答案。'}</div>`}${r.chapters.length?'<div class="qa-highlights">'+r.chapters.map(i=>`<button onclick="openQaChapter(${i})">${qaChapters[i][0]} →</button>`).join(''):' '}`}
function openQaChapter(i){let c=qaChapters[i];modal(`<h2 id="modal-title">${c[0]}</h2><p>${c[1]} · 运营 QA 知识目录</p><div class="video-info">涵盖：${c[2]}</div><div class="notice">当前仅收到目录，未收到本章问答正文。无法展示或引用具体问题的标准答案。</div><div class="modal-footer"><button class="primary" onclick="closeModal()">知道了</button></div>`)}
function renderPrivateRight(){let p=privateState;let name=current==='send'?'群发准备':current==='query'?'统计口径':current==='groups'?'查询范围':current==='qa'?'知识依据':'工作指南';$('#right').innerHTML=`<div class="right-head"><div class="right-title">${name}<span>${['send','query','groups','qa'].includes(current)?'私域数字员工':'全域运营'}</span></div><div class="tabs"><button class="active">${current==='send'?'当前草案':'使用说明'}</button></div></div><div class="panel">${current==='send'?sendRightHtml():current==='query'?`<div class="eyebrow">READ ONLY / STATISTICS</div><h2>让每个指标有明确范围</h2><p class="intro">查询总览、排行、留存、群聊和群发效果，分别展示统计对象与口径。</p><div class="private-summary"><h4>当前查询范围</h4><div class="kv"><span>企业</span><b>${demoCorp().name}</b></div><div class="kv"><span>区间</span><b>${p.start} 至 ${p.end}</b></div><div class="kv"><span>数据源</span><b>本地虚构示例</b></div></div><div class="video-info">触达率 = 已触达 / 目标数量。已发送与已送达分开；任务完成不代表全部触达。</div><p class="private-side-meta">未发送与未触达可能重叠。不同统计维度、时间字段和人群定义需要分别确认，不能直接混合比较。</p>`:current==='groups'?`<div class="eyebrow">READ ONLY / GROUPS</div><h2>查询群信息，不改动群</h2><p class="intro">先选择企业，再按群名、群主、分组缩小范围。</p><div class="private-summary"><h4>${demoCorp().name}</h4><div class="kv"><span>示例群聊</span><b>6 个</b></div><div class="kv"><span>支持查看</span><b>详情 / 成员 / 分组</b></div></div><div class="video-info">客户群聊群发的接收与群主发送明细，在“运营统计 → 群发效果”查看。</div><button class="link" onclick="navigate('query');privateState.statsType='tasks';privateState.taskType='group';render()">查看群发历史统计 →</button>`:current==='qa'?`<div class="eyebrow">KNOWLEDGE / OPERATIONS</div><h2>先有来源，再给答案</h2><div class="private-summary"><h4>当前知识状态</h4><div class="kv"><span>运营 QA 目录</span><b>15 章已载入</b></div><div class="kv"><span>245 条问答正文</span><b>未提供</b></div><div class="kv"><span>可用业务文档</span><b>客户群发 / 统计 / 群查询</b></div></div><p class="private-side-meta">已提供文档可摘要回答。仅有目录时，显示匹配章节与缺失状态，不编造标准答案。</p>`:`<div class="eyebrow">WECAR AI / WORKSPACE</div><h2>两位员工，直接处理业务</h2><p class="intro">按工作能力进入对应页面，客户触达与数据查询都有独立的输入、结果和记录。</p><div class="live-link-card">${icon('users-round')}<div><h4>私域数字员工</h4><p>客户群发 · 运营统计 · 群聊查询 · 运营问答</p></div></div><div class="live-link-card">${icon('clapperboard')}<div><h4>抖音数字员工</h4><p>视频生成 · 直播监控 · 数据监控</p></div></div><div class="video-info">所有数据均为演示。当前不会向外部服务发送客户消息或执行监控。</div>`}</div><div class="panel-actions"><p>本地演示 · 不连接真实客户数据</p><button class="secondary" style="width:100%;margin:0" onclick="navigate('${current==='home'?'send':'home'}')">${current==='home'?'开始准备客户群发':'返回今日工作台'}</button></div>`}
function sendRightHtml(){let p=privateState;return `<div class="eyebrow">CUSTOMER SEND / 1 : 1</div><h2>客户私聊群发</h2><p class="intro">先确认企业和员工，再筛选客户、准备内容并核对范围。</p><div class="panel-label"><span>当前阶段</span><span>0${p.step+1} / 04</span></div>${['选择企业与执行员工','筛选客户与排除范围','准备消息与执行安排','预览确认与保存草案'].map((s,i)=>`<div class="check-row ${p.step===i?'pending':''}" style="${p.step<i?'color:#a6b2aa':''}">${icon(i<p.step?'circle-check':i===p.step?'clock-3':'circle')} ${s}</div>`).join('')}<div class="private-summary"><h4>当前范围</h4><div class="kv"><span>企业</span><b>${demoCorp().name}</b></div><div class="kv"><span>执行员工</span><b>${p.staff.length?p.staff.length+' 人':'待选择'}</b></div><div class="kv"><span>范围预览</span><b>${p.preview?p.preview.matches.length+' 位示例客户':'待预览'}</b></div><div class="kv"><span>接收位置</span><b>客户 1 对 1 私聊</b></div></div><div class="video-info">保存草案不等于任务已创建，更不等于客户已收到。真实执行后，需分别查看员工发送状态与客户送达回执。</div><div class="panel-label">当前会话成果</div><div class="private-side-meta">已保存 ${p.drafts.filter(d=>d.corp===p.corp&&!d.cancelled).length} 份本地草案</div><button class="link" onclick="navigate('files')">查看成果库 →</button>`}
